  ('sample-red-2', 'Sample Red 2', 'Placeholder Cellars', 2020, 'red', 22, 'medium', 'dry', 'medium', 'medium', 'fresh', array['dark-fruit', 'red-berry']::text[], '{}'::text[], array['baking-spice']::text[], array['Pasta with tomato sauce', 'Grilled sausages', 'Hard cheese']::text[], array['dinner-party', 'weeknight']::text[], 'Open it 15 minutes before you pour. It softens as it meets the air.', 'A friendly all-rounder: not too light, not too heavy, easy next to most dinners.', true, array['Wine shops']::text[], null, true),
  ('sample-red-3', 'Sample Red 3', 'Placeholder Cellars', 2019, 'red', 38, 'full', 'dry', 'medium', 'high', 'jammy', array['dark-fruit', 'blue-fruit']::text[], array['purple-flowers']::text[], array['vanilla', 'baking-spice', 'smoke']::text[], array['Steak', 'BBQ ribs', 'Aged cheddar']::text[], array['dinner-party', 'gift']::text[], 'Pour it a little before dinner so it can open up, and serve with something rich.', 'Big and bold, with a dry, grippy feel like strong black tea. Great with grilled meat.', false, array['Wine shops', 'Specialty stores']::text[], null, true),
  ('sample-red-4', 'Sample Red 4', 'Placeholder Cellars', 2021, 'red', 12, 'medium', 'off-dry', 'soft', 'low', 'jammy', array['dark-fruit', 'red-berry']::text[], '{}'::text[], array['vanilla']::text[], array['Burgers', 'BBQ chicken', 'Mild takeout']::text[], array['weeknight', 'gift']::text[], 'Serve it slightly cool. Off-dry reds can taste heavy when warm.', 'Soft and a touch sweet, with ripe fruit. A good one for people who don''t like dry wine.', true, array['Grocery stores']::text[], null, true),
  ('sample-white-1', 'Sample White 1', 'Placeholder Cellars', 2023, 'white', 13, 'light', 'dry', 'zippy', 'low', 'fresh', array['citrus', 'green']::text[], '{}'::text[], '{}'::text[], array['Salad', 'Seafood', 'Goat cheese']::text[], array['weeknight', 'date-night']::text[], 'Serve it well chilled, about 2 hours in the fridge.', 'Crisp and zippy, like lemonade without the sugar. Very refreshing.', true, array['Grocery stores', 'Wine shops']::text[], null, true),
  ('sample-white-2', 'Sample White 2', 'Placeholder Cellars', 2022, 'white', 16, 'medium', 'off-dry', 'zippy', 'low', 'fresh', array['stone-fruit', 'tropical']::text[], array['white-flowers']::text[], '{}'::text[], array['Spicy takeout', 'Thai food', 'Sushi']::text[], array['weeknight', 'date-night']::text[], 'Chill it well. The cool temperature keeps the sweetness in balance with the zip.', 'A little sweet and a little zippy, which is why it calms down spicy food so well.', true, array['Wine shops']::text[], null, true),
  ('sample-white-3', 'Sample White 3', 'Placeholder Cellars', 2020, 'white', 28, 'full', 'dry', 'soft', 'low', 'dried', array['apple-pear', 'stone-fruit']::text[], '{}'::text[], array['toast', 'vanilla']::text[], array['Roast chicken', 'Creamy pasta', 'Lobster']::text[], array['dinner-party', 'date-night']::text[], 'Serve it only lightly chilled. Too cold and you''ll miss the creamy flavors.', 'Rich and round, with a buttery, toasty feel. More cozy than crisp.', false, array['Wine shops', 'Specialty stores']::text[], null, true),
  ('sample-rose-1', 'Sample Rosé 1', 'Placeholder Cellars', 2023, 'rosé', 16, 'light', 'dry', 'zippy', 'low', 'fresh', array['red-berry', 'citrus']::text[], array['roses']::text[], '{}'::text[], array['Salad', 'Grilled shrimp', 'Cheese and crackers']::text[], array['date-night', 'weeknight']::text[], 'Serve it ice cold. It''s made for warm evenings.', 'Pale, dry and strawberry-fresh. A rosé that doesn''t taste like candy.', true, array['Grocery stores', 'Wine shops']::text[], null, true),
  ('sample-bubbly-1', 'Sample Bubbly 1', 'Placeholder Cellars', null, 'sparkling', 24, 'light', 'dry', 'zippy', 'low', 'fresh', array['apple-pear', 'citrus']::text[], array['white-flowers']::text[], array['toast']::text[], array['Salty snacks', 'Fried chicken', 'Cheese and cured meats']::text[], array['gift', 'date-night', 'dinner-party']::text[], 'Chill it for at least 3 hours and open it gently. Hold the cork and twist the bottle.', 'Lively bubbles and green-apple freshness. Good with salty food, and good just because.', true, array['Wine shops', 'Grocery stores']::text[], null, true),
  ('sample-orange-1', 'Sample Orange 1', 'Placeholder Cellars', 2021, 'orange', 32, 'medium', 'dry', 'medium', 'medium', 'dried', array['stone-fruit', 'citrus']::text[], '{}'::text[], array['earthy']::text[], array['Roasted vegetables', 'Hard cheese', 'Spiced dishes']::text[], array['dinner-party']::text[], 'Serve it a little cooler than room temperature, around 55°F.', 'A white wine made like a red, with a gentle grip and a nutty, tea-like taste. Great conversation starter.', false, array['Specialty stores']::text[], null, true)
